// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C, Log} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    Log log;

    function setUp() public {
        log = new Log();
        c = new C(address(log));
    }

    function testFuzz_property(uint256 amount, address actor) public {
        vm.assume(amount > 0 && amount <= 100 ether);
        vm.assume(actor != address(0) && actor != address(c));
        vm.deal(actor, amount);
        uint256 before = log.History(0).Val == 0 && log.History(0).Sender == address(0) ? 0 : 0;
        before = logHistoryLen();
        vm.prank(actor);
        c.Put{value: amount}(0);
        uint256 afterLen = logHistoryLen();
        assertTrue(afterLen == before + 1 && log.History(afterLen - 1).Val == amount && log.History(afterLen - 1).Sender == actor);
    }

    function logHistoryLen() internal view returns (uint256) {
        uint256 i = 0;
        while (true) {
            try this.getHist(i) {
                i++;
            } catch {
                return i;
            }
        }
    }

    function getHist(uint256 i) external view {
        log.History(i);
    }
}

