pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C, Log} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(new Log())); }

    function testFuzz_property(uint256 amount, address actor) public {
        vm.assume(actor != address(0));
        amount = bound(amount, 1, 100 ether);
        vm.deal(actor, amount);
        vm.prank(actor);
        c.Put{value: amount}(0);
        // General rule: after any successful Put(v) by any actor, the newest log
        // entry in c's LogFile History records exactly that deposit.
        (address sender, , uint256 val, ) = c.LogFile().History(0);
        assertTrue(sender == actor && val == amount);
    }
}

// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C, Log} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    Log log;

    function setUp() public {
        log = new Log();
        c = new C(address(log));
    }

    function testFuzz_property(uint256 amount, address actor) public {
        vm.assume(actor != address(0));
        vm.assume(amount > 0);
        vm.assume(amount <= 2 ** 200); // avoid overflow in balance accumulation

        uint256 before = log.History().length;

        vm.deal(actor, amount);
        vm.prank(actor);
        c.Put{value: amount}(0);

        // Rule: every successful Put(v) by actor records exactly one log entry
        // with Sender == actor and Val == v, so History grows by one and the
        // newest entry describes that deposit.
        assertTrue(
            log.History().length == before + 1 &&
            log.History(before + 0).Sender == actor ||
            (log.History().length == before + 1 &&
             log.History(log.History().length - 1).Sender == actor &&
             log.History(log.History().length - 1).Val == amount)
        );
    }
}

