pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C, Log} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    Log logFile;

    function setUp() public { logFile = new Log(); c = new C(address(logFile)); }

    function testFuzz_property(uint256 amount, address actor) public {
        vm.assume(actor != address(0));
        vm.assume(amount > 0 && amount < 1e30 ether);
        vm.deal(actor, amount);

        uint256 lenBefore = logFile.History().length;

        vm.prank(actor);
        c.Put{value: amount}(amount);

        uint256 lenAfter = logFile.History().length;
        (address sender, , uint256 val, ) = logFile.History(lenAfter - 1);

        assertTrue(
            lenAfter == lenBefore + 1 && sender == actor && val == amount,
            "Put must log exactly one History entry for the deposit"
        );
    }
}

