pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C, Log} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(new Log())); }

    function testFuzz_property(address actor, uint256 warpTime, uint256 unlockTime) public {
        vm.assume(actor != address(0));
        vm.warp(warpTime);
        // admissible: the caller asks for an unlock time not in the future
        unlockTime = bound(unlockTime, 0, warpTime);
        vm.deal(actor, 1 wei);
        vm.prank(actor);
        c.Put{value: 0}(unlockTime);
        // general rule: after Put with a non-future _unlockTime, stored unlockTime <= now
        assertTrue(c.Acc(actor).unlockTime <= block.timestamp);
    }
}

