pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C, Log} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(new Log())); }
    function testFuzz_property(uint256 amount, address actor, uint256 unlockTime) public {
        vm.assume(actor != address(0));
        vm.assume(unlockTime < block.timestamp);
        amount = bound(amount, 1 ether, 1000 ether);
        vm.deal(actor, amount);
        vm.prank(actor);
        c.Put{value: amount}(unlockTime);
        bool ok;
        vm.prank(actor);
        try c.Collect(amount) {
            ok = true;
        } catch {
            ok = false;
        }
        assertTrue(ok);
    }
}

contract InvMutTest
{
    C c;

    constructor(C _c) { c = _c; }

    function test(uint amount, uint unlockTime) public
    {
        require(address(this).balance >= amount);
        require(unlockTime < block.timestamp);
        c.Put{value: amount}(unlockTime);
        c.Collect(amount);
        assert(c.Acc(address(this)).balance == 0);
    }

    receive() external payable {}
    fallback() external payable {}
}

