contract InvMutTest {
    C c;
    bool refuse = true;

    constructor(C _c) { c = _c; }

    receive() external payable {
        require(!refuse);
    }

    function run(uint dep, uint am) public {
        require(address(this).balance >= dep);
        c.Put{value: dep}(block.timestamp - 1);
        refuse = true;
        bool ok;
        (ok, ) = address(c).call(abi.encodeWithSelector(c.Collect.selector, am));
        assert(!ok);
    }
}

