contract InvMutTest {
    C c;

    constructor(C _c) { c = _c; }

    function test(uint amt) public {
        require(amt >= c.MinSum());
        require(address(this).balance >= amt);

        // Transaction 1: deposit; unlockTime set to current timestamp
        c.Put{value: amt}(0);

        // Transaction 2: withdraw; succeeds (timestamp advanced, balance >= MinSum)
        c.Collect(amt);

        // The Log contract instance is deployed immediately before C,
        // so its address is C's address minus one.
        address logAddr = address(uint160(uint160(address(c))) - 1);

        // P recorded both the Put and the Collect messages, so History(1) exists.
        // M never recorded the Collect, so History has length 1 and History(1) reverts.
        (bool ok, ) = logAddr.staticcall(abi.encodeWithSignature("History(uint256)", uint256(1)));
        assert(ok);
    }

    receive() external payable {}
    fallback() external payable {}
}
